import{_ as o,o as n,c as e,af as s}from"./chunks/framework.B28LkSoM.js";const h=JSON.parse('{"title":"HTTP响应数据格式与状态码","description":"讲清 HTTP 响应报文的三部分（响应行、响应头、响应体），把状态码 1xx～5xx 五大类各自的意思与责任方说透（200、404、500 三个常见码的场景），再列出 Content-Type 等五个常见响应头字段，并用本机实测的 /hello 与 /nope 响应报文逐行对照","frontmatter":{"title":"HTTP响应数据格式与状态码","published":"2026-09-29T00:00:00.000Z","description":"讲清 HTTP 响应报文的三部分（响应行、响应头、响应体），把状态码 1xx～5xx 五大类各自的意思与责任方说透（200、404、500 三个常见码的场景），再列出 Content-Type 等五个常见响应头字段，并用本机实测的 /hello 与 /nope 响应报文逐行对照","tags":["JavaWeb","HTTP"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-34-http-response-status(1).webp","order":34,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/34-HTTP响应数据格式与状态码.md","filePath":"posts/学习文档/JavaWeb学习笔记/34-HTTP响应数据格式与状态码.md"}'),d={name:"posts/学习文档/JavaWeb学习笔记/34-HTTP响应数据格式与状态码.md"};function a(r,t,c,g,l,p){return n(),e("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1790640000000"},[...t[0]||(t[0]=[s(`<p><a href="/posts/编程学习/javaweb学习笔记/33-springboot获取请求数据/">33 篇</a>讲的是请求方向——<strong>服务器怎么拿到浏览器发来的数据</strong>。这一篇（PPT 第 32～38 页）翻到另一半：<strong>服务器回给浏览器的响应数据长什么样</strong>，以及响应行里那个&quot;状态码&quot;到底怎么读。代码层面&quot;怎么把响应写出来&quot;是下一篇（35 篇）的事，这一篇先把<strong>格式</strong>看清楚。</p><h2 id="一次-http-交互的两半-ppt-第-32-34-页" tabindex="-1">一次 HTTP 交互的两半（PPT 第 32～34 页） <a class="header-anchor" href="#一次-http-交互的两半-ppt-第-32-34-页" aria-label="Permalink to &quot;一次 HTTP 交互的两半（PPT 第 32～34 页）&quot;">​</a></h2><p>PPT 第 32、33 页是这两节的小目录，把 HTTP 协议排成了四格：<strong>请求数据格式 → 请求数据获取 → 响应数据格式 → 响应数据设置</strong>。前两格是 <a href="/posts/编程学习/javaweb学习笔记/32-http协议与请求数据格式/">32 篇</a>和 <a href="/posts/编程学习/javaweb学习笔记/33-springboot获取请求数据/">33 篇</a>，这一篇是第三格。</p><p>PPT 第 34 页又把 HTTP 协议的定义复习了一遍：</p><blockquote><p><strong>概念：Hyper Text Transfer Protocol，超文本传输协议，规定了浏览器和服务器之间数据传输的规则。</strong></p></blockquote><p>一次交互就是<strong>一问一答</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 ──── 请求数据（请求行 / 请求头 / 请求体）────► 服务器</span></span>
<span class="line"><span>浏览器 ◄─── 响应数据（响应行 / 响应头 / 响应体）──── 服务器</span></span></code></pre></div><p>请求数据的三部分在 <a href="/posts/编程学习/javaweb学习笔记/32-http协议与请求数据格式/">32 篇</a>里讲过了，这一篇要记住的是：<strong>响应数据的三部分名字一一对应</strong>——请求那边第一行叫请求行，响应这边第一行就叫<strong>响应行</strong>；请求头对<strong>响应头</strong>；请求体对<strong>响应体</strong>。</p><h2 id="响应数据的三部分-ppt-第-35-页" tabindex="-1">响应数据的三部分（PPT 第 35 页） <a class="header-anchor" href="#响应数据的三部分-ppt-第-35-页" aria-label="Permalink to &quot;响应数据的三部分（PPT 第 35 页）&quot;">​</a></h2><p>PPT 第 35 页给的定义：</p><blockquote><p><strong>响应行：响应数据第一行（协议、状态码、描述）</strong><strong>响应头：第二行开始，格式 <code>key：value</code></strong><strong>响应体：最后一部分，存放响应数据</strong></p></blockquote><p>拿 PPT 里那段真实响应报文对照着看：</p><p><img src="https://img.tsh520.cn/file/blog/article/35-HTTP%E5%93%8D%E5%BA%94%E6%8A%A5%E6%96%87%E5%AE%9E%E4%BE%8B.jpg" alt="HTTP响应报文实例"><em>图：PPT 第 35 页配的响应报文——第一行 <code>HTTP/1.1 200 OK</code> 是<strong>响应行</strong>（协议 <code>HTTP/1.1</code>、状态码 <code>200</code>、描述 <code>OK</code>）；往下 <code>Content-Type</code>、<code>Transfer-Encoding</code>、<code>Date</code>、<code>Keep-Alive</code>、<code>Connection</code> 这几行键值对是<strong>响应头</strong>；再空一行之后，最后那段 <code>[{&quot;id&quot;: 1, &quot;brandName&quot;: &quot;阿里巴巴&quot;, …}]</code> 是<strong>响应体</strong>（一份 JSON 数据）。注意响应头和响应体之间那个<strong>空行</strong>——它和请求报文里分隔请求头/请求体的空行是同一个作用</em></p><p>三点补充：</p><ul><li><strong>空行是分隔符</strong>，不是可有可无的装饰：响应头到空行就结束了，空行后面才轮到响应体；响应体可以为空（比如 204 这种&quot;成功但没内容&quot;的响应）；</li><li><strong>响应行里的&quot;描述&quot;<strong>只是给人看的文字说明（<code>OK</code>、<code>Not Found</code>、<code>Unauthorized</code>），程序判断成功失败看的是</strong>数字状态码</strong>；</li><li><strong>列表里响应头的顺序不重要</strong>，<code>key：value</code> 是一行一条，名字不区分大小写。</li></ul><h2 id="响应状态码-五大类-ppt-第-36-页" tabindex="-1">响应状态码：五大类（PPT 第 36 页） <a class="header-anchor" href="#响应状态码-五大类-ppt-第-36-页" aria-label="Permalink to &quot;响应状态码：五大类（PPT 第 36 页）&quot;">​</a></h2><p>PPT 第 36 页把状态码按第一位数字分成五类：</p><table tabindex="0"><thead><tr><th>分类</th><th>含义（PPT 原文）</th><th>责任在谁</th><th>典型状态码</th></tr></thead><tbody><tr><td><strong>1xx</strong></td><td><strong>响应中</strong>——临时状态码，表示请求已经接收，告诉客户端应该继续请求或者如果它已经完成则忽略它</td><td>不算错误，是过程提示</td><td>100 Continue</td></tr><tr><td><strong>2xx</strong></td><td><strong>成功</strong>——表示请求已经被成功接收，处理已完成</td><td>一切正常</td><td><strong>200</strong></td></tr><tr><td><strong>3xx</strong></td><td><strong>重定向</strong>——重定向到其他地方；让客户端再发起一次请求以完成整个处理</td><td>客户端需要<strong>再发一次请求</strong></td><td>301（永久）、302（临时）</td></tr><tr><td><strong>4xx</strong></td><td><strong>客户端错误</strong>——处理发生错误，责任<strong>在客户端</strong>。如：请求了不存在的资源、客户端未被授权、禁止访问等</td><td>客户端（请求写错了）</td><td><strong>404</strong>、401、403</td></tr><tr><td><strong>5xx</strong></td><td><strong>服务器错误</strong>——处理发生错误，责任<strong>在服务端</strong>。如：程序抛出异常等</td><td>服务端（程序出问题了）</td><td><strong>500</strong></td></tr></tbody></table><p>记这一张表的诀窍：<strong>看首位数字就够</strong>——<code>4</code> 开头怪请求方，<code>5</code> 开头怪服务端，<code>3</code> 开头是&quot;你要换个地址再问一次&quot;，<code>1</code> 开头是&quot;还没完，继续&quot;，只有 <code>2</code> 开头是&quot;成了&quot;。</p><h3 id="三个最常见状态码-ppt-第-37-页" tabindex="-1">三个最常见状态码（PPT 第 37 页） <a class="header-anchor" href="#三个最常见状态码-ppt-第-37-页" aria-label="Permalink to &quot;三个最常见状态码（PPT 第 37 页）&quot;">​</a></h3><p>PPT 第 37 页把最常打交道的三个单独列了一张表：</p><table tabindex="0"><thead><tr><th>状态码</th><th>描述（PPT 原文）</th><th>平时遇到它的场景</th></tr></thead><tbody><tr><td><strong>200</strong></td><td><strong>客户端请求成功</strong></td><td>一切正常——接口返回数据、页面正常打开，浏览器 F12 里满眼都是 200</td></tr><tr><td><strong>404</strong></td><td><strong>请求资源不存在，URL 输入有误，或者网站资源被删除了</strong></td><td>地址敲错、接口路径改了名字、静态资源被删；属于 <strong>4xx 客户端错误</strong></td></tr><tr><td><strong>500</strong></td><td><strong>服务器发生不可预期的错误</strong></td><td>后端代码抛异常（空指针、除零、SQL 写错…）；属于 <strong>5xx 服务端错误</strong></td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>排查问题时这两个码的用法完全不同：<strong>看到 404 先怀疑地址</strong>（前端请求的路径和后端 <code>@RequestMapping</code> 里的值对不上、静态资源放错目录），<strong>看到 500 去翻服务器日志</strong>（堆栈会告诉你哪一行抛的异常）。这也解释了 PPT 第 36 页对 4xx/5xx 的&quot;责任划分&quot;——它决定了你该去改前端还是改后端。</p></div><h2 id="五个常见响应头字段-ppt-第-36-页" tabindex="-1">五个常见响应头字段（PPT 第 36 页） <a class="header-anchor" href="#五个常见响应头字段-ppt-第-36-页" aria-label="Permalink to &quot;五个常见响应头字段（PPT 第 36 页）&quot;">​</a></h2><p>PPT 第 36 页列了五个最常见的响应头字段：</p><table tabindex="0"><thead><tr><th>响应头</th><th>作用（PPT 原文）</th><th>说明与例子</th></tr></thead><tbody><tr><td><strong><code>Content-Type</code></strong></td><td>表示该响应内容的<strong>类型</strong></td><td>例如 <code>text/html</code>（网页）、<code>application/json</code>（接口数据）、<code>text/plain</code>（纯文本）；本机实测返回字符串时服务器写的是 <code>text/plain;charset=UTF-8</code>，返回对象/集合时是 <code>application/json</code></td></tr><tr><td><strong><code>Content-Length</code></strong></td><td>表示该响应内容的<strong>长度（字节数）</strong></td><td>本机实测返回 <code>Hello Tom~</code> 时是 <code>Content-Length: 10</code>（10 个 ASCII 字符 = 10 字节）；用了分块传输（<code>Transfer-Encoding: chunked</code>）时就没有它</td></tr><tr><td><strong><code>Content-Encoding</code></strong></td><td>表示该响应<strong>压缩算法</strong></td><td>例如 <code>gzip</code>；浏览器请求头里带 <code>Accept-Encoding: gzip, deflate, br</code>（见<a href="/posts/编程学习/javaweb学习笔记/32-http协议与请求数据格式/">32 篇</a>）就是为了告诉服务器&quot;我能解压这些&quot;</td></tr><tr><td><strong><code>Cache-Control</code></strong></td><td>指示客户端应如何<strong>缓存</strong></td><td>例如 <code>max-age=300</code> 表示可以最多缓存 300 秒</td></tr><tr><td><strong><code>Set-Cookie</code></strong></td><td>告诉浏览器为当前页面所在的域<strong>设置 cookie</strong></td><td>响应方向的&quot;种 cookie&quot;，与请求头里的 <code>Cookie</code>（浏览器把 cookie 带回去）配成一对</td></tr></tbody></table><p><code>Content-Type</code> 和 <code>Content-Length</code> 这两个是日常调试里出现频率最高的：一个说&quot;这是什么&quot;，一个说&quot;它有多大&quot;。</p><h2 id="_3xx-是怎么回事-重定向-ppt-第-36-页" tabindex="-1">3xx 是怎么回事：重定向（PPT 第 36 页） <a class="header-anchor" href="#_3xx-是怎么回事-重定向-ppt-第-36-页" aria-label="Permalink to &quot;3xx 是怎么回事：重定向（PPT 第 36 页）&quot;">​</a></h2><p>PPT 第 36 页右下角画了一张重定向示意图：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 ──①请求 A──► 服务器</span></span>
<span class="line"><span>客户端 ◄──② 3xx (Location：B)── 服务器        ← 服务器说&quot;你要的东西在 B&quot;</span></span>
<span class="line"><span>客户端 ──③再请求 B──► 服务器</span></span>
<span class="line"><span>客户端 ◄──④ 最终响应── 服务器</span></span></code></pre></div><p>要点就是 PPT 那句&quot;<strong>让客户端再发起一次请求以完成整个处理</strong>&quot;：</p><ul><li>服务器<strong>不会</strong>替客户端去访问 B，它只是回一个 3xx，并在响应头里用 <strong><code>Location</code></strong> 告诉客户端新地址；</li><li>客户端（浏览器）收到 3xx 后<strong>自动</strong>再发一次请求，这次才拿到真正的数据——所以浏览器地址栏会&quot;跳&quot;到新地址；</li><li>302 与 301 的差别在&quot;临时还是永久&quot;（301 永久重定向，浏览器和搜索引擎会记住新地址；302 临时），这也是它属于 3xx 而不是 4xx 的原因：<strong>这不是错误，只是流程没走完</strong>。</li></ul><h2 id="实测-亲眼看看真实响应的三部分" tabindex="-1">实测：亲眼看看真实响应的三部分 <a class="header-anchor" href="#实测-亲眼看看真实响应的三部分" aria-label="Permalink to &quot;实测：亲眼看看真实响应的三部分&quot;">​</a></h2><p>拿<a href="/posts/编程学习/javaweb学习笔记/30-springboot快速入门/">30 篇</a>那个 <code>/hello</code> 接口抓一次响应报文，三部分一眼可辨：</p><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p><strong>本机实测</strong>（Spring Boot 3.2.8 / 内嵌 Tomcat 10.1.26 / JDK 17）——请求 <code>curl -si &quot;http://localhost:8080/hello?name=Tom&quot; | head -5</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 200 </span></span>
<span class="line"><span>Content-Type: text/plain;charset=UTF-8</span></span>
<span class="line"><span>Content-Length: 10</span></span>
<span class="line"><span>Date: Tue, 29 Sep 2026 07:39:29 GMT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hello Tom~</span></span></code></pre></div><p>逐行对照 PPT 第 35 页的三部分：第一行 <code>HTTP/1.1 200 </code> 是<strong>响应行</strong>（协议 + 状态码 200 + 描述，Tomcat 这里没填描述文字）；中间三行 <code>Content-Type</code> / <code>Content-Length</code> / <code>Date</code> 是<strong>响应头</strong>；空行之后那行 <code>Hello Tom~</code> 是<strong>响应体</strong>，长度 10 字节与 <code>Content-Length: 10</code> 对得上。</p><p>同一个工程里请求一个<strong>不存在的地址</strong>（<code>curl -s -o /dev/null -w &quot;%{http_code}&quot; &quot;http://localhost:8080/nope&quot;</code>），拿到的状态码是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>404</span></span></code></pre></div><p>这正是 PPT 第 37 页说的&quot;请求资源不存在，URL 输入有误&quot;——<code>/nope</code> 这个路径没有任何 <code>@RequestMapping</code> 与之匹配，属于 <strong>4xx 客户端错误</strong>。</p><p>换个返回内容的接口，<code>Content-Type</code> 会跟着变（同一台机器上请求返回 JSON 的 <code>/list</code> 接口，<code>curl -si &quot;http://localhost:8080/list&quot; | head -4</code>）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 200</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span>Transfer-Encoding: chunked</span></span></code></pre></div><p>返回的是集合，所以类型是 <code>application/json</code>；这次因为长度要边算边发（分块传输），响应头里是 <code>Transfer-Encoding: chunked</code> 而<strong>没有</strong> <code>Content-Length</code>——和上一条对照着看，<code>Content-Length</code> 与 <code>Transfer-Encoding</code> 是二选一的两种&quot;告诉客户端有多长&quot;的方式。</p></div><h2 id="必答问答-ppt-第-38-页" tabindex="-1">必答问答（PPT 第 38 页） <a class="header-anchor" href="#必答问答-ppt-第-38-页" aria-label="Permalink to &quot;必答问答（PPT 第 38 页）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>PPT 的问题</th><th>答案</th></tr></thead><tbody><tr><td>HTTP响应数据分为几个部分？</td><td><strong>三部分——响应行、响应头、响应体</strong>（响应行是协议、状态码、描述；响应头是 <code>key：value</code>；响应体放响应数据）</td></tr><tr><td>响应状态码的分类？</td><td><strong>1xx 响应中</strong>（临时状态码）；<strong>2xx 成功</strong>；<strong>3xx 重定向</strong>；<strong>4xx 客户端错误</strong>；<strong>5xx 服务端错误</strong></td></tr></tbody></table><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>响应数据分几部分？</td><td><strong>响应行</strong>（协议、状态码、描述）、<strong>响应头</strong>（第二行开始，<code>key：value</code>）、<strong>响应体</strong>（最后一部分，与响应头之间<strong>隔一个空行</strong>）</td></tr><tr><td>状态码五大类怎么分？</td><td><strong>1xx 响应中</strong>（临时）；<strong>2xx 成功</strong>；<strong>3xx 重定向</strong>（让客户端再发一次请求）；<strong>4xx 客户端错误</strong>（如 404）；<strong>5xx 服务端错误</strong>（如 500）</td></tr><tr><td>200 / 404 / 500 分别是什么？</td><td><strong>200 客户端请求成功</strong>；<strong>404 请求资源不存在，URL 输入有误，或者网站资源被删除了</strong>；<strong>500 服务器发生不可预期的错误</strong>（程序抛异常）</td></tr><tr><td>常见响应头有哪些？</td><td><strong>Content-Type</strong>（响应内容类型，如 <code>text/html</code>、<code>application/json</code>）、<strong>Content-Length</strong>（内容长度，字节数）、<strong>Content-Encoding</strong>（压缩算法，如 gzip）、<strong>Cache-Control</strong>（缓存指示，如 <code>max-age=300</code>）、<strong>Set-Cookie</strong>（给当前域设置 cookie）</td></tr><tr><td>3xx 重定向的过程？</td><td>客户端请求 A → 服务器回 <strong>3xx + <code>Location: B</code></strong> → 客户端<strong>再发起一次请求</strong>到 B → 拿到最终响应；服务器不替客户端去取 B</td></tr><tr><td>实测里响应头长什么样？</td><td><code>/hello</code> 返回 <code>200</code> + <code>Content-Type: text/plain;charset=UTF-8</code> + <code>Content-Length: 10</code> + <code>Date</code>；返回 JSON 的接口是 <code>Content-Type: application/json</code> + <code>Transfer-Encoding: chunked</code>（这次没有 Content-Length）；请求不存在的路径得到 <strong>404</strong></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/javaweb学习笔记/33-springboot获取请求数据/">上一篇：SpringBoot获取请求数据</a></li><li><a href="/posts/编程学习/javaweb学习笔记/35-springboot设置响应数据/">下一篇：SpringBoot设置响应数据</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li><strong>响应数据三部分</strong>：<strong>响应行</strong>（第一行，含协议、状态码、描述）、<strong>响应头</strong>（第二行开始，<code>key：value</code>）、<strong>响应体</strong>（最后一部分，存放响应数据）；<strong>响应头和响应体之间隔了一个空行</strong></li><li><strong>状态码五大类</strong>：<strong>1xx 响应中</strong>（临时状态码，告诉客户端继续请求或忽略）、<strong>2xx 成功</strong>（请求已被成功接收、处理已完成）、<strong>3xx 重定向</strong>（让客户端再发起一次请求以完成整个处理）、<strong>4xx 客户端错误</strong>（责任在客户端，如请求了不存在的资源、未被授权、禁止访问）、<strong>5xx 服务端错误</strong>（责任在服务端，如程序抛出异常）</li><li><strong>三个常见状态码</strong>：<strong>200 客户端请求成功</strong>；<strong>404 请求资源不存在，URL 输入有误，或者网站资源被删除了</strong>；<strong>500 服务器发生不可预期的错误</strong></li><li><strong>责任划分的用法</strong>：看到 <strong>404 先怀疑地址</strong>（前端请求路径与后端映射对不上、静态资源放错位置），看到 <strong>500 去翻服务器日志</strong>（堆栈会指出哪一行抛的异常）</li><li><strong>五个常见响应头</strong>：<strong>Content-Type</strong>（响应内容类型，如 <code>text/html</code>、<code>application/json</code>、<code>text/plain</code>）、<strong>Content-Length</strong>（响应内容长度，单位字节）、<strong>Content-Encoding</strong>（压缩算法，如 <code>gzip</code>）、<strong>Cache-Control</strong>（缓存指示，如 <code>max-age=300</code> 表示最多缓存 300 秒）、<strong>Set-Cookie</strong>（告诉浏览器为当前页面所在的域设置 cookie）</li><li><strong>响应行的构成</strong>：协议（如 <code>HTTP/1.1</code>）+ <strong>状态码</strong>（数字，程序看它）+ 描述（给人看的文字，如 <code>OK</code>）；本机实测 <code>/hello</code> 的响应行是 <code>HTTP/1.1 200</code>（Tomcat 没填描述文字）</li><li><strong>本机实测的响应头</strong>：返回字符串时 <code>Content-Type: text/plain;charset=UTF-8</code>、<code>Content-Length: 10</code>（<code>Hello Tom~</code> 正好 10 字节）、<code>Date: …</code>；返回集合（JSON）时 <code>Content-Type: application/json</code> 且是 <code>Transfer-Encoding: chunked</code>（<strong>没有 Content-Length</strong>）；请求不存在的路径（<code>/nope</code>）返回 <strong>404</strong></li><li><strong>Content-Length 与 Transfer-Encoding 的关系</strong>：两者都是&quot;告诉客户端响应体有多长/怎么读&quot;的方式，长度事先算得出就用 <code>Content-Length</code>，一边生成一边发就用 <code>Transfer-Encoding: chunked</code>（分块传输），一般<strong>不同时出现</strong></li><li><strong>3xx 重定向的过程</strong>：客户端请求 A → 服务器返回 <strong>3xx + <code>Location: B</code></strong> → 客户端<strong>再发起一次请求</strong>到 B → 得到最终响应（301 永久 / 302 临时）；服务器不会替客户端去访问 B</li><li><strong>PPT 第 38 页两个必答问答</strong>：响应数据分为 → <strong>响应行、响应头、响应体</strong>；状态码分类 → <strong>1xx 响应中、2xx 成功、3xx 重定向、4xx 客户端错误、5xx 服务端错误</strong></li></ol><h3 id="二、裸写题" tabindex="-1">二、裸写题 <a class="header-anchor" href="#二、裸写题" aria-label="Permalink to &quot;二、裸写题&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1 给一段响应报文&quot;分段&quot;</strong> 下面这段报文是一次请求的响应原文：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 404 </span></span>
<span class="line"><span>Content-Type: text/html;charset=UTF-8</span></span>
<span class="line"><span>Content-Length: 48</span></span>
<span class="line"><span>Date: Tue, 29 Sep 2026 07:39:29 GMT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;html&gt;&lt;body&gt;&lt;h1&gt;404 Not Found&lt;/h1&gt;&lt;/body&gt;&lt;/html&gt;</span></span></code></pre></div><p>请照着本篇的三段划分，把每一行属于哪一部分标出来，并回答：</p><ol><li>响应头是从第几行开始、到第几行结束？响应头和响应体之间靠什么分隔？</li><li>这段响应的状态码是多少、属于哪一类、责任在客户端还是服务端？描述里说的场景是什么？</li><li><code>Content-Type</code> 的值是什么、说明响应体是什么类型的内容？<code>Content-Length</code> 的值和响应体字节数对得上吗？ （练习文件 <code>test_34_响应报文三部分.txt</code> 里给了写作区。）</li></ol><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：先按&quot;第一行 / 中间一堆键值对 / 空行 / 最后的正文&quot;切三刀，再回到本篇的状态码表和响应头表里查含义；字节数可以用&quot;ASCII 字符 1 个算 1 字节&quot;去数 <strong>二级 · 方法</strong>：第一行是<strong>响应行</strong>（协议、状态码、描述）；<code>key：value</code> 那些行是<strong>响应头</strong>；空行之后是<strong>响应体</strong>；4 开头的状态码查&quot;客户端错误&quot;那一行，<code>Content-Type</code>/<code>Content-Length</code> 查响应头表 <strong>三级 · 骨架</strong>：<code>第 1 行 = ____行；第 2～4 行 = ____；第 5 行 = ____；第 6 行 = ____；状态码 ____ 属于 ____，责任在____</code></p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-1</strong></p><ol><li>分段结果：<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 404                                             ← 响应行</span></span>
<span class="line"><span>Content-Type: text/html;charset=UTF-8                    ← 响应头</span></span>
<span class="line"><span>Content-Length: 48                                       ← 响应头</span></span>
<span class="line"><span>Date: Tue, 29 Sep 2026 07:39:29 GMT                      ← 响应头</span></span>
<span class="line"><span>                                                         ← 空行（分隔响应头与响应体）</span></span>
<span class="line"><span>&lt;html&gt;&lt;body&gt;&lt;h1&gt;404 Not Found&lt;/h1&gt;&lt;/body&gt;&lt;/html&gt;         ← 响应体</span></span></code></pre></div></li><li>响应头从<strong>第 2 行</strong>开始、到<strong>第 4 行</strong>结束（共 3 条），响应头和响应体之间靠<strong>一个空行</strong>分隔。状态码是 <strong>404</strong>，属于 <strong>4xx 客户端错误</strong>，责任在<strong>客户端</strong>；PPT 第 37 页的描述是&quot;<strong>请求资源不存在，URL 输入有误，或者网站资源被删除了</strong>&quot;——正好对应这段响应体里写的 <code>404 Not Found</code>。</li><li><code>Content-Type</code> 的值是 <code>text/html;charset=UTF-8</code>，说明响应体是 <strong>HTML 网页内容</strong>、字符集是 UTF-8；<code>Content-Length</code> 是 <strong>48</strong>，而响应体 <code>&lt;html&gt;&lt;body&gt;&lt;h1&gt;404 Not Found&lt;/h1&gt;&lt;/body&gt;&lt;/html&gt;</code> 是 48 个 ASCII 字符 = 48 字节，<strong>完全对得上</strong>（换成中文就不行了：UTF-8 下一个汉字算 3 字节）。</li></ol></details></li><li><p>[ ] <strong>2-2 给一组状态码&quot;归类定责&quot;</strong> 下面这些状态码出现在各种请求结果里，请逐个判断：① 属于哪一类（1xx～5xx）？② 大概是什么意思？③ 出问题时该去改客户端还是改服务端？ <code>200</code>、<code>204</code>、<code>301</code>、<code>302</code>、<code>403</code>、<code>404</code>、<code>500</code>、<code>503</code> 做完在文件末尾用一句话总结：<strong>只凭状态码的第一位数字，能判断出什么？</strong> （练习文件 <code>test_34_状态码分类.txt</code> 里给了写作区。）</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：不用背全部，先按首位数字分堆（1/2/3/4/5），再回到本篇那五行含义里找对应；责任归属就写在 4xx 和 5xx 那两行里 <strong>二级 · 方法</strong>：2 开头 = 成功；3 开头 = 重定向（别忘 301 永久 / 302 临时）；4 开头 = 客户端错误（404 找不到资源、403 禁止访问）；5 开头 = 服务端错误（500 程序抛异常、503 服务不可用） <strong>三级 · 骨架</strong>：<code>200 → ____类，____，责任在____</code>（其余同理，一条一行）</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-2</strong></p><table tabindex="0"><thead><tr><th>状态码</th><th>分类</th><th>含义</th><th>该改哪边</th></tr></thead><tbody><tr><td>200</td><td><strong>2xx 成功</strong></td><td>客户端请求成功，处理已完成</td><td>都不用改（正常）</td></tr><tr><td>204</td><td><strong>2xx 成功</strong></td><td>请求成功但没有响应体（成功类里唯一&quot;没内容&quot;的）</td><td>都不用改</td></tr><tr><td>301</td><td><strong>3xx 重定向</strong></td><td>资源<strong>永久</strong>换地址了，客户端按 <code>Location</code> 再请求一次并记住新地址</td><td>客户端（浏览器自动跳）/ 服务端配的跳转</td></tr><tr><td>302</td><td><strong>3xx 重定向</strong></td><td><strong>临时</strong>重定向，客户端按 <code>Location</code> 再请求一次</td><td>同上</td></tr><tr><td>403</td><td><strong>4xx 客户端错误</strong></td><td>禁止访问（PPT 第 36 页 4xx 描述里的&quot;禁止访问&quot;）</td><td>客户端（请求方没有权限/路径不对）</td></tr><tr><td>404</td><td><strong>4xx 客户端错误</strong></td><td>请求资源不存在，URL 输入有误，或者网站资源被删除了</td><td>客户端（先查地址/路径）</td></tr><tr><td>500</td><td><strong>5xx 服务端错误</strong></td><td>服务器发生不可预期的错误（程序抛异常）</td><td>服务端（翻日志看堆栈）</td></tr><tr><td>503</td><td><strong>5xx 服务端错误</strong></td><td>服务器暂时不可用/过载（同样是服务端的事）</td><td>服务端</td></tr></tbody></table><p>一句话总结：<strong>只看第一位数字就能定&quot;大方向&quot;和&quot;责任方&quot;</strong>——1 过程提示、2 成功、3 要再请求一次、4 客户端有错、5 服务端有错。</p></details></li><li><p>[ ] <strong>2-3 手写一段能返回 JSON 的响应报文</strong> 后端要返回一份用户数据，响应体是 <code>{&quot;id&quot;:1,&quot;username&quot;:&quot;daqiao&quot;}</code>。请把这整段 HTTP 响应报文<strong>完整写出来</strong>（按本篇的三部分格式），要求：</p><ol><li>状态行说明协议、这次是成功、描述写 <code>OK</code>；</li><li>响应头里给出 <code>Content-Type</code>（这份数据是 JSON 格式）和 <code>Content-Length</code>（<strong>字节数要算对</strong>）；</li><li>再补一个 <code>Date</code> 响应头（值随意）；</li><li>空一行，然后才是响应体；</li><li>在文件末尾回答两个问题：① 这份报文里哪些部分<strong>不需要程序员手写</strong>（对照<a href="/posts/编程学习/javaweb学习笔记/30-springboot快速入门/">30 篇</a>里 <code>/hello</code> 的实测响应，那里状态码和响应头是谁写的）？② 如果响应体换成汉字内容，<code>Content-Length</code> 还能用字符个数去数吗？ （练习文件 <code>test_34_手写响应报文.txt</code> 里给了写作区。）</li></ol><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：照抄本篇实测那段响应的&quot;形状&quot;，只把里面的值和内容换掉；长度要<strong>数字节</strong>——这段响应体全是 ASCII 字符，一个字符一个字节 <strong>二级 · 方法</strong>：第一行形如 <code>协议 状态码 描述</code>（成功是 200，描述 OK）；头部 JSON 的类型是 <code>application/json</code>；<code>Content-Length</code> 用&quot;字符个数&quot;数出来；空行之后再写 JSON <strong>三级 · 骨架</strong>：<code>HTTP/1.1 ____ OK</code> / <code>Content-Type: ____</code> / <code>Content-Length: ____</code> / <code>Date: ____</code> / 空行 / <code>{&quot;id&quot;:1,&quot;username&quot;:&quot;daqiao&quot;}</code></p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-3</strong> 完整报文：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span>Content-Length: 28</span></span>
<span class="line"><span>Date: Tue, 29 Sep 2026 07:39:29 GMT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{&quot;id&quot;:1,&quot;username&quot;:&quot;daqiao&quot;}</span></span></code></pre></div><p>格式核对：第 1 行是响应行（协议 <code>HTTP/1.1</code>、状态码 <code>200</code>、描述 <code>OK</code>）；第 2～4 行是响应头（<code>key: value</code>）；第 5 行是<strong>空行</strong>；第 6 行是响应体。 两个问题： ① 状态行里的<strong>状态码、描述</strong>和那几条<strong>响应头全都不是手写的</strong>——本机实测（Spring Boot 3.2.8 / 内嵌 Tomcat）里 <code>/hello</code> 接口的响应是 <code>HTTP/1.1 200 </code> + <code>Content-Type: text/plain;charset=UTF-8</code> + <code>Content-Length: 10</code> + <code>Date: …</code>，代码里只是 <code>return &quot;Hello &quot; + name + &quot;~&quot;;</code>，这些头都是<strong>服务器自动设置</strong>的（下一篇 35 篇会讲为什么&quot;通常不用手动设置&quot;）。这里手写只是为了看清报文的格式。 ② <strong>不能</strong>。<code>Content-Length</code> 的单位是<strong>字节数</strong>，而 UTF-8 下一个汉字占 <strong>3 个字节</strong>（如 <code>&quot;阿里巴巴&quot;</code> 4 个字 = 12 字节），必须按编码后的字节数算，不能按字符个数数。</p></details></li></ul><h3 id="三、综合题" tabindex="-1">三、综合题 <a class="header-anchor" href="#三、综合题" aria-label="Permalink to &quot;三、综合题&quot;">​</a></h3><ul><li><p>[ ] <strong>3-1 亲手抓一次响应，逐部分分析并验证 200 / 404 / 500</strong> 把自己工程里的响应报文抓下来分析一遍，顺便把三种状态码都见一次。</p><ol><li>启动自己的 SpringBoot 工程，找一个<strong>能正常访问</strong>的接口（比如 <code>/hello?name=Tom</code>）；</li><li>用 <code>curl -i</code>（或浏览器 F12 → Network → 点某条请求 → Headers）抓下完整响应，把响应行、响应头、响应体三部分几行抄到练习文件里，并在每行后面标出它属于哪一部分；</li><li>数一数这次响应有几个响应头，指出其中哪个是 <code>Content-Type</code>、值是什么，并从值判断响应体是什么类型的内容；</li><li>把地址换成一个<strong>不存在的路径</strong>（如 <code>/nope</code>）再访问一次，记下状态码，判断它属于哪一类、责任在客户端还是服务端、该去哪边排查；</li><li>在自己某个接口的代码里<strong>故意制造一个异常</strong>（例如让一个整数除以 0），重新访问它，记下状态码，判断分类与责任方，并从控制台日志里找出是哪一行代码抛的异常；</li><li>最后在文件末尾回答 PPT 第 38 页的两个问题（响应数据分为哪几个部分、状态码怎么分类）。 （练习文件 <code>test_34_综合_抓取并分析响应报文.txt</code> 里按这 6 步给了写作区。）</li></ol><p><strong>涉及知识点</strong></p><table tabindex="0"><thead><tr><th>知识点</th><th>在这里的应用</th></tr></thead><tbody><tr><td>响应数据三部分</td><td>抓包后逐行标注响应行 / 响应头 / 响应体</td></tr><tr><td>状态码五大类</td><td>第 4 步的 404 属于 4xx；第 5 步的 500 属于 5xx</td></tr><tr><td>责任划分</td><td>404 查地址、500 翻日志（决定改前端还是改后端）</td></tr><tr><td>常见响应头</td><td><code>Content-Type</code> 判断内容类型，<code>Content-Length</code> 核对字节数</td></tr><tr><td>服务器自动设置</td><td>代码里没写状态码和响应头，它们照样出现在报文里</td></tr></tbody></table><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：先用一个正常接口建立&quot;标准形状&quot;，再拿两个异常场景（地址错 / 程序错）作对照，三份报文放一起就是这一篇的完整证据链；第 5 步的异常只要让代码在运行时抛出来就行 <strong>二级 · 方法</strong>：抓报文用 <code>curl -i</code> 加上接口地址（<code>-i</code> = 连响应头一起打印，等价做法是浏览器 F12 的 Network 面板）；不认识的路径 → 没有 <code>@RequestMapping</code> 匹配 → 404；代码抛异常 → 服务器返回 500，堆栈在 IDEA 控制台里 <strong>三级 · 骨架</strong>：<code>curl -i &quot;http://localhost:8080/____&quot;</code> → 抄三部分；再 <code>curl -i &quot;http://localhost:8080/____&quot;</code>（不存在的路径）→ 记状态码；最后在方法里加一行 <code>int x = 1 / 0;</code> 再访问 → 记状态码 + 抄堆栈第一行</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>3-1</strong> 2. 正常接口的响应（<strong>本机实测</strong>，Spring Boot 3.2.8 / 内嵌 Tomcat 10.1.26 / JDK 17，<code>curl -si &quot;http://localhost:8080/hello?name=Tom&quot; | head -5</code>）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 200                                   ← 响应行（协议、状态码、描述）</span></span>
<span class="line"><span>Content-Type: text/plain;charset=UTF-8         ← 响应头</span></span>
<span class="line"><span>Content-Length: 10                             ← 响应头</span></span>
<span class="line"><span>Date: Tue, 29 Sep 2026 07:39:29 GMT            ← 响应头</span></span>
<span class="line"><span>                                               ← 空行（分隔响应头与响应体）</span></span>
<span class="line"><span>Hello Tom~                                     ← 响应体</span></span></code></pre></div><ol start="3"><li>这次响应共 <strong>3 个响应头</strong>（<code>Content-Type</code>、<code>Content-Length</code>、<code>Date</code>），其中 <code>Content-Type</code> 的值是 <strong><code>text/plain;charset=UTF-8</code></strong>——说明响应体是<strong>纯文本、UTF-8 编码</strong>；本机另外实测了返回集合的 <code>/list</code> 接口，它的 <code>Content-Type</code> 是 <code>application/json</code>（且因为分块传输是 <code>Transfer-Encoding: chunked</code>，没有 <code>Content-Length</code>），可见这个头是<strong>跟着响应内容变的</strong>。</li><li>访问不存在的路径（<strong>本机实测</strong>）：<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ curl -s -o /dev/null -w &quot;%{http_code}&quot; &quot;http://localhost:8080/nope&quot;</span></span>
<span class="line"><span>404</span></span></code></pre></div><strong>404</strong> 属于 <strong>4xx 客户端错误</strong>，责任在<strong>客户端</strong>：PPT 第 37 页的描述是&quot;请求资源不存在，URL 输入有误，或者网站资源被删除了&quot;。排查思路是先怀疑<strong>地址</strong>——检查请求的路径和 Controller 上 <code>@RequestMapping</code> 的值是否一致（<a href="/posts/编程学习/javaweb学习笔记/33-springboot获取请求数据/">33 篇</a>里 <code>getRequestURI()</code> 取到的正是这个路径）。</li><li>故意在方法里制造异常（例如加一行 <code>int result = 1 / 0;</code>）后再访问，响应状态码是 <strong>500</strong>（&quot;服务器发生不可预期的错误&quot;，属于 <strong>5xx 服务端错误</strong>，责任在服务端）；IDEA 控制台会打印异常堆栈，第一行通常是 <code>java.lang.ArithmeticException: / by zero</code>，顺着堆栈就能定位到抛异常的那一行。<strong>这就是 404 与 500 的分工：一个先去改地址，一个先去翻日志。</strong></li><li>PPT 第 38 页两个问题： ① 响应数据分为 <strong>三部分——响应行、响应头、响应体</strong>； ② 状态码分类：<strong>1xx 响应中（临时状态码）、2xx 成功、3xx 重定向、4xx 客户端错误、5xx 服务端错误</strong>。</li></ol></details></li></ul>`,48)])])}const u=o(d,[["render",a]]);export{h as __pageData,u as default};
